from pathlib import Path
import re

p=Path('experience.html')
text=p.read_text(encoding='utf-8')

old_section=re.compile(r'<section class="decisionBox expTabPanel" id="formatFinder" data-exp-panel="recommend">.*?</section>',re.S)
new_section='''<section class="decisionBox expTabPanel" id="formatFinder" data-exp-panel="recommend"><h2>作品から上映方式を選ぶ</h2><p>作品を検索し、候補から正しい作品を選んで確定してから上映方式のおすすめを表示します。</p><div class="filmPicker"><input id="formatFilm" type="search" placeholder="作品名を入力（例：オデュッセイア）" aria-label="上映方式を選ぶ作品名"><button id="formatJudge" type="button">作品を検索</button></div><div class="filmCandidates" id="formatCandidates" hidden></div><button id="formatConfirm" class="formatConfirm" type="button" disabled hidden>この作品で確定</button><div class="formatResult" id="formatResult"><div class="decisionNote">作品名を入力して検索してください。</div></div></section>'''
text,n=old_section.subn(new_section,text,count=1)
if n!=1: raise SystemExit('formatFinder section not found')

style_marker='<style id="experience-tabs-v1">'
css='''<style id="experience-candidate-selection-v1">\n.filmCandidates{display:grid;gap:7px;margin-top:10px}.filmCandidate{width:100%;text-align:left;border:1px solid #30343a;background:#0a0c0f;color:#f1f1f1;border-radius:10px;padding:10px 11px;display:flex;align-items:center;justify-content:space-between;gap:10px}.filmCandidate b{font-size:13px}.filmCandidate span{font-size:10px;color:#858d96;white-space:nowrap}.filmCandidate.selected{border-color:#e7dfd2;background:#171717;box-shadow:0 0 0 1px #e7dfd255}.formatConfirm{margin-top:10px;width:100%;border:1px solid #e5ddd0;background:#f2eee6;color:#111;border-radius:9px;padding:11px 13px;font-weight:800}.formatConfirm:disabled{opacity:.4}.formatScoreActions{display:flex;gap:10px;flex-wrap:wrap;margin-top:5px}.formatReasonToggle,.formatScoreCta{appearance:none;border:0;background:transparent;padding:0;font:inherit;font-size:10px!important;font-weight:750;text-decoration:underline;text-underline-offset:3px;cursor:pointer}.formatReasonToggle{color:#b8c0c8}.formatReasonBody{display:none;margin-top:5px;padding:8px 9px;border-left:2px solid #3b4148;background:#0a0c0f;color:#aeb5bd!important;line-height:1.55}.formatReasonBody.show{display:block}\n</style>\n\n'''
if 'experience-candidate-selection-v1' not in text:
    text=text.replace(style_marker,css+style_marker,1)

script_re=re.compile(r'<script id="experience-decision-js-v1">.*?</script>',re.S)
new_script='''<script id="experience-decision-js-v1">(()=>{const input=document.getElementById('formatFilm'),searchBtn=document.getElementById('formatJudge'),confirmBtn=document.getElementById('formatConfirm'),candidateBox=document.getElementById('formatCandidates'),out=document.getElementById('formatResult');if(!input||!searchBtn||!confirmBtn||!candidateBox||!out)return;let candidates=[];let selectedMovie=null;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const clamp=n=>Math.max(1,Math.min(5,n));const stars=n=>'★'.repeat(Math.round(n))+'☆'.repeat(5-Math.round(n));function genresOf(m){return (m.genres||m.genre_names||[]).map(x=>String(typeof x==='string'?x:(x&&x.name)||'').toLowerCase()).join(' ')}function scoreMovie(m){const g=genresOf(m),s={'通常上映':4,'IMAX':3.5,'Dolby Cinema':3.5,'4DX / MX4D':2,'ScreenX':2};if(/action|アクション|adventure|アドベンチャー|science fiction|sf|fantasy|ファンタジー/.test(g)){s.IMAX+=1;s['Dolby Cinema']+=.5;s['4DX / MX4D']+=.8;s.ScreenX+=.4}if(/horror|ホラー|thriller|スリラー|crime|犯罪/.test(g)){s['Dolby Cinema']+=1;s.IMAX+=.3;s['4DX / MX4D']+=.3}if(/animation|アニメ/.test(g)){s.IMAX+=.6;s['Dolby Cinema']+=.5;s.ScreenX+=.2}if(/drama|ドラマ|romance|恋愛|documentary|ドキュメンタリー/.test(g)){s['通常上映']+=.5;s['Dolby Cinema']+=.2;s['4DX / MX4D']-=.8;s.ScreenX-=.5}Object.keys(s).forEach(k=>s[k]=clamp(s[k]));return s}function reason(k){return k==='IMAX'?'大画面・スケール感との相性':k==='Dolby Cinema'?'黒・コントラストと立体音響':k==='4DX / MX4D'?'動きのある場面を身体で楽しむ':k==='ScreenX'?'左右まで広がる視界を楽しむ':'追加演出なしで作品に集中'}function tabFor(k){return k==='IMAX'?'aspect':k==='Dolby Cinema'?'visual':k==='4DX / MX4D'||k==='ScreenX'?'special':null}function tabLabel(k){return k==='IMAX'?'画角を詳しく見る':k==='Dolby Cinema'?'映像を詳しく見る':k==='4DX / MX4D'||k==='ScreenX'?'体感を詳しく見る':''}function movieYear(m){const d=m.release_date||m.first_air_date||m.year||'';return String(d).slice(0,4)}function renderCandidates(){candidateBox.hidden=!candidates.length;candidateBox.innerHTML=candidates.map((m,i)=>'<button type="button" class="filmCandidate" data-candidate-index="'+i+'"><b>'+esc(m.title||m.name||'タイトル不明')+'</b><span>'+esc(movieYear(m)||'年不明')+'</span></button>').join('');candidateBox.querySelectorAll('[data-candidate-index]').forEach(el=>el.addEventListener('click',()=>{const i=Number(el.dataset.candidateIndex);selectedMovie=candidates[i];candidateBox.querySelectorAll('.filmCandidate').forEach(x=>x.classList.toggle('selected',x===el));confirmBtn.disabled=false;confirmBtn.hidden=false;out.innerHTML='<div class="decisionNote"><b>'+esc(selectedMovie.title||selectedMovie.name||input.value.trim())+'</b>を選択中。確定するとおすすめを表示します。</div>'}))}async function search(){const q=input.value.trim();if(!q)return;selectedMovie=null;candidates=[];confirmBtn.disabled=true;confirmBtn.hidden=true;candidateBox.hidden=true;searchBtn.disabled=true;out.innerHTML='<div class="decisionNote">候補を検索中…</div>';try{const r=await fetch('https://backend-one-gray-94.vercel.app/api/movies?q='+encodeURIComponent(q)+'&limit=8',{cache:'no-store'}),d=await r.json();const seen=new Set();candidates=[...(d.movies||[]),...(d.external||[])].filter(m=>{const key=String(m.tmdbId||m.id||'')+'|'+String(m.title||m.name||'')+'|'+movieYear(m);if(seen.has(key))return false;seen.add(key);return true}).slice(0,6);if(!candidates.length)throw 0;renderCandidates();out.innerHTML='<div class="decisionNote">候補から作品を1つ選んでください。</div>'}catch(e){out.innerHTML='<div class="decisionNote">作品候補を取得できませんでした。作品名を変えて再検索してください。</div>'}finally{searchBtn.disabled=false}}function renderRecommendation(){if(!selectedMovie)return;const scores=scoreMovie(selectedMovie),rows=[['通常上映',scores['通常上映']],...Object.entries(scores).filter(([k])=>k!=='通常上映').sort((a,b)=>b[1]-a[1])];const title=selectedMovie.title||selectedMovie.name||input.value.trim();out.innerHTML='<div class="decisionNote"><b>'+esc(title)+'</b>の作品傾向からの目安</div>'+rows.map(([k,v])=>{const target=tabFor(k),tabLink=target?'<button type="button" class="formatScoreCta" data-go-tab="'+target+'">'+tabLabel(k)+' →</button>':'';return '<div class="formatScore"><b>'+k+'</b><strong>'+stars(v)+'</strong><span class="formatScoreMeta"><span>'+reason(k)+'</span><span class="formatScoreActions"><button type="button" class="formatReasonToggle" aria-expanded="false">理由を見る</button>'+tabLink+'</span><span class="formatReasonBody">'+reason(k)+'。作品ジャンルとの相性を基準にした目安で、作品固有の上映仕様は未確認なら加点していません。</span></span></div>'}).join('')+'<div class="decisionNote">※ジャンル等からの目安です。作品固有の上映仕様・上映有無は劇場公式情報を確認してください。</div>';out.querySelectorAll('.formatReasonToggle').forEach(b=>b.addEventListener('click',()=>{const body=b.closest('.formatScoreMeta')?.querySelector('.formatReasonBody');if(!body)return;const open=!body.classList.contains('show');body.classList.toggle('show',open);b.setAttribute('aria-expanded',open?'true':'false');b.textContent=open?'理由を閉じる':'理由を見る'}));out.querySelectorAll('[data-go-tab]').forEach(el=>el.addEventListener('click',()=>window.switchExperienceTab&&window.switchExperienceTab(el.dataset.goTab,true)))}searchBtn.addEventListener('click',search);confirmBtn.addEventListener('click',renderRecommendation);input.addEventListener('input',()=>{selectedMovie=null;confirmBtn.disabled=true;confirmBtn.hidden=true});input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();search()}})})();</script>'''
text,n=script_re.subn(new_script,text,count=1)
if n!=1: raise SystemExit('decision script not found')

p.write_text(text,encoding='utf-8')
